  transition: color 180ms, background-color 180ms;
}
.kalos-dropzone-actions button:hover {
  color: var(--kalos-dz-ink);
  background: var(--kalos-dz-hover);
}
.kalos-dropzone-actions button svg { width: 13px; height: 13px; stroke-width: 1.6; }
.kalos-dropzone-summary {
  display: flex;
  min-height: 40px;
  flex-wrap: wrap;
  align-content: center;
  align-items: center;
  gap: 0 8px;
  margin: 0 -8px;
  border-top: 1px solid var(--kalos-dz-edge);
  padding: 8px 14px;
  font-variant-numeric: tabular-nums;
}
.kalos-dropzone-list:empty + .kalos-dropzone-summary { margin-top: 8px; }
.kalos-dropzone-summary > span + span::before { content: "· "; }
.kalos-dropzone-summary[data-uploading] > span:first-child {
  --kalos-dz-summary-gradient: linear-gradient(105deg, var(--kalos-dz-muted) 30%, var(--kalos-dz-ink) 50%, var(--kalos-dz-muted) 70%);
  background-image: var(--kalos-dz-summary-gradient);
  background-size: 220% 100%;
  background-clip: text;
  color: transparent;
  animation: kalos-dz-shimmer 1.7s linear infinite;
}
.kalos-dropzone-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  clip-path: inset(50%);
  overflow: hidden;
  white-space: nowrap;
}
@media (pointer: coarse) {
  .kalos-dropzone-actions button { width: 34px; height: 34px; }
}
@keyframes kalos-dz-shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-3px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}
@keyframes kalos-dz-check {
  0% { opacity: 0; transform: scale(0.55); }
  72% { opacity: 1; transform: scale(1.13); }
  100% { opacity: 1; transform: scale(1); }
}
@keyframes kalos-dz-tick { to { stroke-dashoffset: 0; } }
@keyframes kalos-dz-title {
  from { opacity: 0; transform: translateY(2px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes kalos-dz-shimmer {
  from { background-position: 120% 0; }
  to { background-position: -120% 0; }
}
