"use client";

import * as React from "react";
import { NumberField } from "@base-ui/react/number-field";
import { Minus, Plus } from "lucide-react";
import { Field, FieldLabel } from "@/components/ui/field";
import { KalosFieldMessage } from "@/components/ui/kalos-field-message";
import { KalosNumberInputValue, useNumberInputMotion, useNumberInputReset } from "@/components/ui/kalos-number-input-parts";
import { clampNumber, stepNumber, type KalosNumberInputProps } from "@/components/ui/kalos-number-input-model";
import { controlStyles } from "@/components/ui/kalos-styles";
import { cn } from "@/lib/utils";

type Props = Omit<KalosNumberInputProps, "onValueChange"> & {
  onValueChange?: NumberField.Root.Props["onValueChange"];
  onValueCommitted?: NumberField.Root.Props["onValueCommitted"];
};
export type { Props as KalosNumberInputProps };

export function KalosNumberInput({ label, value, defaultValue = null, onValueChange, onValueCommitted, min, max, step = 1, largeStep = step * 10, prefix, unit, locale = "zh-CN", formatOptions, hint, error, id, name, form, disabled, readOnly, required, className, inputClassName, ref, onKeyDown, ...props }: Props) {
  const autoId = React.useId();
  const fieldId = id ?? autoId;
  const messageId = `${fieldId}-description`;
  const inputRef = React.useRef<HTMLInputElement>(null);
  const [internal, setInternal] = React.useState(() => clampNumber(defaultValue, min, max));
  const current = value !== undefined ? value : internal;
  const committed = React.useRef(current);
  const [restoreRevision, setRestoreRevision] = React.useState(0);
  React.useLayoutEffect(() => { if (restoreRevision) inputRef.current?.focus(); }, [restoreRevision]);
  useNumberInputMotion(inputRef, current);
  useNumberInputReset(inputRef, () => { setInternal(clampNumber(defaultValue, min, max)); committed.current = clampNumber(defaultValue, min, max); });
  return <Field data-invalid={!!error} data-disabled={disabled || undefined} className={cn("gap-1.5", className)}>
    <FieldLabel htmlFor={fieldId} onClickCapture={event => { event.preventDefault(); event.stopPropagation(); }} className={controlStyles.label}>{label}{required ? <span aria-hidden="true" className={controlStyles.requiredMark}>*</span> : null}</FieldLabel>
    <NumberField.Root key={restoreRevision} id={fieldId} value={current} min={min} max={max} step={step} largeStep={largeStep} smallStep={step} snapOnStep locale={locale} format={{ maximumFractionDigits: 20, ...formatOptions }} name={name} form={form} disabled={disabled} readOnly={readOnly} required={required}
      onValueChange={(next, details) => { onValueChange?.(next, details); if (!details.isCanceled && value === undefined) setInternal(next); }}
      onValueCommitted={(next, details) => { committed.current = next; onValueCommitted?.(next, details); }}>
      <NumberField.Group data-invalid={!!error} data-disabled={disabled || undefined} className={cn(controlStyles.inputGroup, "items-center")}>
        <KalosNumberInputValue prefix={prefix} unit={unit}>
          <NumberField.Input {...props} role="spinbutton" aria-valuenow={current ?? undefined} aria-valuemin={min} aria-valuemax={max} ref={element => { inputRef.current = element; if (typeof ref === "function") ref(element); else if (ref) ref.current = element; }} className={cn(controlStyles.numberInput, inputClassName)}
            aria-invalid={!!error || props["aria-invalid"]} aria-describedby={[props["aria-describedby"], error || hint ? messageId : undefined].filter(Boolean).join(" ") || undefined}
            aria-valuetext={current === null ? undefined : [typeof prefix === "string" ? prefix : "", new Intl.NumberFormat(locale, { maximumFractionDigits: 20, ...formatOptions }).format(current), unit].filter(Boolean).join(" ")}
            onFocus={event => { committed.current = current; props.onFocus?.(event); }}
            onKeyDown={event => {
              onKeyDown?.(event);
              if (event.defaultPrevented || event.nativeEvent.isComposing || disabled || readOnly) return;
              if (["PageUp", "PageDown", "Escape"].includes(event.key)) {
                event.preventDefault();
                const next = event.key === "Escape" ? committed.current : stepNumber(current, event.key === "PageUp" ? 1 : -1, step, min, max, largeStep);
                const details: NumberField.Root.ChangeEventDetails = { reason: "keyboard", event: event.nativeEvent, trigger: event.currentTarget, cancel() { this.isCanceled = true; }, allowPropagation() { this.isPropagationAllowed = true; }, isCanceled: false, isPropagationAllowed: false };
                if (next !== current) onValueChange?.(next, details);
                if (!details.isCanceled) {
                  if (value === undefined) setInternal(next);
                  if (event.key === "Escape") setRestoreRevision(revision => revision + 1);
                  else { committed.current = next; onValueCommitted?.(next, { reason: "keyboard", event: event.nativeEvent }); }
                }
              }
            }} />
        </KalosNumberInputValue>
        <div className={controlStyles.numberActions}>
          <NumberField.Decrement tabIndex={-1} aria-label={`减少${label}`} aria-controls={fieldId} className={controlStyles.numberAction}><Minus aria-hidden="true" /></NumberField.Decrement>
          <NumberField.Increment tabIndex={-1} aria-label={`增加${label}`} aria-controls={fieldId} className={controlStyles.numberAction}><Plus aria-hidden="true" /></NumberField.Increment>
        </div>
      </NumberField.Group>
    </NumberField.Root>
    <KalosFieldMessage id={messageId} hint={hint} error={error} />
  </Field>;
}

"use client";

import * as React from "react";
import { controlStyles, numberInputSettings } from "@/components/ui/kalos-styles";
import { cn } from "@/lib/utils";

export function KalosNumberInputValue({ prefix, unit, children }: { prefix?: React.ReactNode; unit?: string; children: React.ReactNode }) {
  return <div className={controlStyles.numberValue}>
    {prefix != null ? <span aria-hidden="true" className={controlStyles.numberAffix}>{prefix}</span> : null}
    {children}
    {unit ? <span aria-hidden="true" className={cn(controlStyles.numberAffix, "ml-1.5")}>{unit}</span> : null}
  </div>;
}

export function useNumberInputMotion(inputRef: React.RefObject<HTMLInputElement | null>, value: number | null) {
  const previous = React.useRef(value);
  React.useEffect(() => {
    const old = previous.current;
    previous.current = value;
    const input = inputRef.current;
    if (!input || old === value || old === null || value === null || document.activeElement === input) return;
    const animation = input.animate([
      { transform: `translateY(${value > old ? 3 : -3}px)`, opacity: 0.45 },
      { transform: "translateY(0)", opacity: 1 },
    ], { duration: numberInputSettings.duration, easing: "cubic-bezier(0.22, 1, 0.36, 1)" });
    return () => animation.cancel();
  }, [inputRef, value]);
}

export function useNumberInputReset(inputRef: React.RefObject<HTMLInputElement | null>, reset: () => void) {
  const onReset = React.useEffectEvent(reset);
  React.useEffect(() => {
    const form = inputRef.current?.form;
    if (!form) return;
    const handleReset = (event: Event) => queueMicrotask(() => { if (!event.defaultPrevented) onReset(); });
    form.addEventListener("reset", handleReset);
    return () => form.removeEventListener("reset", handleReset);
  }, [inputRef]);
}

import type { ComponentProps, ReactNode } from "react";

export type KalosNumberInputProps = Omit<ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type" | "size" | "min" | "max" | "step" | "prefix"> & {
  label: string;
  value?: number | null;
  defaultValue?: number | null;
  onValueChange?: (value: number | null) => void;
  min?: number;
  max?: number;
  step?: number;
  largeStep?: number;
  prefix?: ReactNode;
  unit?: string;
  locale?: string;
  formatOptions?: Intl.NumberFormatOptions;
  hint?: string;
  error?: string;
  inputClassName?: string;
};

export function clampNumber(value: number | null, min = -Infinity, max = Infinity) {
  return value === null || !Number.isFinite(value) ? null : Math.min(Math.max(value, min), max);
}

export function stepNumber(value: number | null, direction: number, step = 1, min = -Infinity, max = Infinity, amount = step) {
  const safeStep = Number.isFinite(step) && step > 0 ? step : 1;
  const origin = Number.isFinite(min) ? min : 0;
  const start = value ?? (Number.isFinite(min) ? min : Number.isFinite(max) && max < 0 ? max : 0);
  if (value === null) return clampNumber(start, min, max);
  const position = (start - origin) / safeStep;
  const rounded = Math.round(position);
  const aligned = Math.abs(position - rounded) < 1e-8;
  const next = aligned
    ? start + direction * amount
    : origin + (direction > 0 ? Math.ceil(position) : Math.floor(position)) * safeStep;
  return clampNumber(Number(next.toPrecision(15)), min, max);
}

export function createNumberFormatter(locale = "zh-CN", options: Intl.NumberFormatOptions = {}) {
  const formatter = new Intl.NumberFormat(locale, { maximumFractionDigits: 20, ...options });
  const parts = formatter.formatToParts(-12345.6);
  const decimal = new Intl.NumberFormat(locale).formatToParts(1.1).find(part => part.type === "decimal")?.value ?? ".";
  const groups = new Set(parts.filter(part => part.type === "group").map(part => part.value));
  const symbols = parts.filter(part => ["currency", "percentSign", "unit", "literal"].includes(part.type)).map(part => part.value);
  const digits = Array.from({ length: 10 }, (_, digit) => new Intl.NumberFormat(locale, { useGrouping: false }).format(digit));
  return {
    format: (value: number | null) => value === null ? "" : formatter.format(value),
    parse(text: string): number | null {
      let normalized = text.trim();
      if (!normalized) return null;
      digits.forEach((digit, value) => { normalized = normalized.replaceAll(digit, String(value)); });
      for (const group of groups) normalized = normalized.replaceAll(group, "");
      for (const symbol of symbols) normalized = normalized.replaceAll(symbol, "");
      normalized = normalized.replaceAll(decimal, ".").replace(/[−﹣－]/g, "-").replace(/[\s\u200e\u200f\u061c]/g, "");
      if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized)) return NaN;
      const value = Number(normalized) / (options.style === "percent" ? 100 : 1);
      return Number.isFinite(value) ? value : NaN;
    },
  };
}

"use client";

import { useEffect, useEffectEvent, useId, useRef, useState, type ComponentPropsWithRef, type CSSProperties, type KeyboardEvent, type PointerEvent } from "react";
import { DirectionProvider } from "@base-ui/react/direction-provider";
import { Popover } from "@base-ui/react/popover";
import { Radio } from "@base-ui/react/radio";
import { RadioGroup } from "@base-ui/react/radio-group";
import { Slider } from "@base-ui/react/slider";
import { Hash } from "lucide-react";
import { InputGroup, InputGroupInput } from "@/components/ui/input-group";
import { clampColor, colorToHsva, completeColorInput, defaultColor, hsvaToHex, normalizeColor, type Hsva } from "@/components/ui/kalos-color-picker-model";
import { colorPickerCss, colorPickerStyleHref } from "@/components/ui/kalos-color-picker-styles";
import { controlStyles } from "@/components/ui/kalos-styles";
import { cn } from "@/lib/utils";

export type KalosColorPreset = string | { value: string; label: string };

type ColorValueProps = {
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  alpha?: boolean;
  presets?: readonly KalosColorPreset[];
};

export type KalosColorPickerProps = Omit<ComponentPropsWithRef<"button">, "value" | "defaultValue" | "onChange" | "children" | "type"> & ColorValueProps & {
  label?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: Popover.Root.Props["onOpenChange"];
  showValue?: boolean;
  size?: "sm" | "md";
  side?: "bottom" | "top";
  align?: "start" | "end";
};

export type KalosColorPickerPanelProps = Omit<ComponentPropsWithRef<"div">, "defaultValue" | "onChange" | "children"> & ColorValueProps;

function useColorValue({ value, defaultValue, onValueChange, alpha = false }: ColorValueProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue ?? defaultColor);
  const hex = normalizeColor(value ?? uncontrolled, alpha) ?? defaultColor;
  const [edit, setEdit] = useState(() => ({ hex, color: colorToHsva(hex) }));
  let color = edit.color;
  if (edit.hex !== hex) {
    color = colorToHsva(hex, edit.color);
    setEdit({ hex, color });
  }

  function change(next: Hsva) {
    const nextHex = hsvaToHex(next, alpha);
    setEdit({ hex: nextHex, color: next });
    if (hex === nextHex) return;
    if (value === undefined) setUncontrolled(nextHex);
    onValueChange?.(nextHex);
  }

  function reset() {
    const initial = defaultValue ?? defaultColor;
    const initialHex = normalizeColor(initial, alpha) ?? defaultColor;
    setUncontrolled(initial);
    setEdit({ hex: initialHex, color: colorToHsva(initialHex) });
  }

  return { hex, color, alpha, change, reset };
}

type ColorValue = ReturnType<typeof useColorValue>;

function PickerStyles() {
  return <style href={colorPickerStyleHref} precedence="default">{colorPickerCss}</style>;
}

function colorStyle(color: string): CSSProperties {
  return { "--color-swatch": color } as CSSProperties;
}

function ColorPlane({ color, change }: ColorValue) {
  const saturation = Math.round(color.s * 100);
  const brightness = Math.round(color.v * 100);
  function drag(event: PointerEvent<HTMLDivElement>) {
    const rect = event.currentTarget.getBoundingClientRect();
    change({ ...color, s: clampColor((event.clientX - rect.left) / rect.width), v: clampColor(1 - (event.clientY - rect.top) / rect.height) });
  }
  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const step = event.shiftKey ? 10 : 1;
    const moves: Record<string, [number, number]> = {
      ArrowLeft: [-step, 0], ArrowRight: [step, 0], ArrowUp: [0, step], ArrowDown: [0, -step],
      PageUp: [0, 10], PageDown: [0, -10], Home: [-100, 0], End: [100, 0],
    };
    if (!Object.hasOwn(moves, event.key)) return;
    event.preventDefault();
    const [s, v] = moves[event.key];
    change({ ...color, s: s ? clampColor((saturation + s) / 100) : color.s, v: v ? clampColor((brightness + v) / 100) : color.v });
  }
  return (
    <div className="kalos-color-plane" dir="ltr" role="slider" tabIndex={0} aria-label="饱和度与明度"
      aria-valuemin={0} aria-valuemax={100} aria-valuenow={saturation}
      aria-valuetext={`饱和度 ${saturation}%，明度 ${brightness}%`}
      onKeyDown={onKeyDown}
      onPointerDown={(event) => {
        if (!event.isPrimary || event.button !== 0) return;
        event.preventDefault();
        event.currentTarget.setPointerCapture(event.pointerId);
        event.currentTarget.focus({ preventScroll: true });
        drag(event);
      }}
      onPointerMove={(event) => {
        if (event.currentTarget.hasPointerCapture(event.pointerId)) drag(event);
      }}
      onPointerUp={(event) => {
        if (event.currentTarget.hasPointerCapture(event.pointerId)) drag(event);
      }}
    >
      <span aria-hidden="true" className="kalos-color-thumb" style={{ left: `${color.s * 100}%`, top: `${(1 - color.v) * 100}%` }} />
    </div>
  );
}

function ColorSliders({ color, alpha, change }: ColorValue) {
  return <DirectionProvider direction="ltr">
    <Slider.Root dir="ltr" value={Math.round(color.h)} max={360} thumbAlignment="edge"
      onValueChange={(h) => change({ ...color, h })}>
      <Slider.Control className="kalos-color-track" data-channel="hue">
        <Slider.Thumb className="kalos-color-thumb" getAriaLabel={() => "色相"} getAriaValueText={(_, value) => `${value}°`} />
      </Slider.Control>
    </Slider.Root>
    {alpha ? <Slider.Root dir="ltr" value={Math.round(color.a * 100)} max={100} thumbAlignment="edge"
      onValueChange={(value) => change({ ...color, a: value / 100 })}>
      <Slider.Control className="kalos-color-track" data-channel="alpha">
        <Slider.Thumb className="kalos-color-thumb kalos-color-swatch" getAriaLabel={() => "不透明度"} getAriaValueText={(_, value) => `${value}%`} />
      </Slider.Control>
    </Slider.Root> : null}
  </DirectionProvider>;
}

function ColorField({ hex, color, alpha, change }: ColorValue) {
  const [draft, setDraft] = useState<string>();
  const [invalid, setInvalid] = useState(false);

  function commit(input: string) {
    const next = normalizeColor(input, alpha);
    if (!next) return false;
    if (next !== hex) change(colorToHsva(next, color));
    return true;
  }

  return <div className="flex min-w-0 items-center gap-2" dir="ltr">
    <span aria-hidden="true" className="kalos-color-swatch size-8 rounded-[7px] [@media(pointer:coarse)]:size-10" />
    <InputGroup className={cn(controlStyles.inputGroup, "relative [@media(pointer:coarse)]:h-10")} data-invalid={invalid || undefined}>
      <Hash aria-hidden="true" className="pointer-events-none absolute left-2.5 size-3 text-muted-foreground" />
      <InputGroupInput
        className={cn(controlStyles.inputContent, "kalos-color-code pl-7")}
        aria-label="十六进制颜色"
        aria-invalid={invalid || undefined}
        value={draft ?? hex.slice(1).toUpperCase()}
        spellCheck={false}
        autoComplete="off"
        autoCapitalize="off"
        onChange={(event) => {
          const text = event.target.value;
          setDraft(text);
          setInvalid(false);
          if (completeColorInput.test(text.trim())) commit(text);
        }}
        onBlur={() => {
          if (draft !== undefined) commit(draft);
          setDraft(undefined);
          setInvalid(false);
        }}
        onKeyDown={(event) => {
          if (event.key !== "Enter" || event.nativeEvent.isComposing) return;
          event.preventDefault();
          if (draft === undefined) return;
          if (commit(draft)) setDraft(undefined);
          else setInvalid(true);
        }}
      />
      {invalid ? <span className="sr-only" role="alert">请输入有效的 HEX 或 RGB 颜色</span> : null}
    </InputGroup>
    {alpha ? <span className="w-9 shrink-0 text-right text-xs text-muted-foreground tabular-nums">{Math.round(color.a * 100)}%</span> : null}
  </div>;
}

function ColorPresets({ value, presets }: { value: ColorValue; presets?: readonly KalosColorPreset[] }) {
  const options = new Map<string, string>();
  for (const preset of presets ?? []) {
    const hex = normalizeColor(typeof preset === "string" ? preset : preset.value, value.alpha);
    if (hex && !options.has(hex)) options.set(hex, typeof preset === "string" ? hex.toUpperCase() : preset.label);
  }
  if (!options.size) return null;
  return (
    <RadioGroup aria-label="预设颜色" className="kalos-color-presets" value={value.hex}
      onValueChange={(hex) => value.change(colorToHsva(hex, value.color))}>
      {[...options].map(([hex, label]) => (
        <Radio.Root key={hex} value={hex} className="kalos-color-preset kalos-color-swatch"
          aria-label={label} title={label}
          style={{ ...colorStyle(hex), "--color-preset-ring": hex.slice(0, 7) } as CSSProperties} />
      ))}
    </RadioGroup>
  );
}

function ColorPanel({ state, presets, className, style, ...props }: ComponentPropsWithRef<"div"> & {
  state: ColorValue;
  presets?: readonly KalosColorPreset[];
}) {
  return (
    <div {...props} className={cn("kalos-color-panel", className)} style={{
      "--color-swatch": state.hex,
      "--color-solid": state.hex.slice(0, 7),
      "--color-hue": `hsl(${state.color.h} 100% 50%)`,
      ...style,
    } as CSSProperties}>
      <ColorPlane {...state} />
      <ColorSliders {...state} />
      <ColorField {...state} />
      <ColorPresets value={state} presets={presets} />
    </div>
  );
}

export function KalosColorPickerPanel({ value, defaultValue, onValueChange, alpha, presets, className, ...props }: KalosColorPickerPanelProps) {
  const state = useColorValue({ value, defaultValue, onValueChange, alpha });
  return <>
    <PickerStyles />
    <ColorPanel {...props} data-inline="" className={cn(controlStyles.popover, className)}
      state={state} presets={presets} />
  </>;
}

export function KalosColorPicker({
  value, defaultValue, onValueChange, alpha, presets, name, open, defaultOpen = false, onOpenChange,
  label = "颜色", showValue = true, side = "bottom", align = "start", size = "md", className,
  id, disabled, form, "aria-label": ariaLabel, ...props
}: KalosColorPickerProps) {
  const state = useColorValue({ value, defaultValue, onValueChange, alpha });
  const [internalOpen, setOpen] = useState(defaultOpen);
  const expanded = !disabled && (open ?? internalOpen);
  const popup = useRef<HTMLDivElement>(null);
  const canFocusPopup = useRef(!expanded);
  const hiddenInput = useRef<HTMLInputElement>(null);
  const generatedId = useId();
  const triggerId = id ?? generatedId;
  const displayHex = state.hex.slice(0, 7).toUpperCase();
  const opacity = Math.round(state.color.a * 100);
  const buttonLabel = ariaLabel ?? `${label}，${displayHex}${alpha && opacity < 100 ? `，不透明度 ${opacity}%` : ""}`;

  useEffect(() => {
    if (!expanded) canFocusPopup.current = true;
  }, [expanded]);

  const reset = useEffectEvent(state.reset);
  useEffect(() => {
    const owner = hiddenInput.current?.form;
    if (!owner || value !== undefined) return;
    function handleReset(event: Event) {
      queueMicrotask(() => { if (!event.defaultPrevented) reset(); });
    }
    owner.addEventListener("reset", handleReset);
    return () => owner.removeEventListener("reset", handleReset);
  }, [form, name, value]);

  return <>
    <PickerStyles />
    <Popover.Root open={expanded} triggerId={triggerId} onOpenChange={(next, details) => {
      onOpenChange?.(next, details);
      if (open === undefined && !details.isCanceled) setOpen(next);
    }}>
      <Popover.Trigger {...props} id={triggerId} form={form} disabled={disabled} aria-label={buttonLabel}
        className={cn(controlStyles.button, controlStyles.buttonSurface,
          "kalos-color-trigger inline-flex shrink-0 items-center justify-center gap-1.5 px-2 align-middle aria-expanded:shadow-[var(--k-shadow-hover)]",
          size === "sm" ? "h-7 [@media(pointer:coarse)]:h-9" : "h-8 [@media(pointer:coarse)]:h-10",
          !showValue && "aspect-square px-0", className)}>
        <span className={cn("kalos-color-swatch rounded-[5px]", size === "sm" ? "size-4" : "size-[18px]")}
          style={colorStyle(state.hex)} aria-hidden="true" />
        {showValue ? <span className="kalos-color-code inline-flex items-center gap-1.5" dir="ltr" aria-hidden="true">
          {displayHex}{alpha ? <span className="w-[4ch] text-right text-muted-foreground">{opacity}%</span> : null}
        </span> : null}
      </Popover.Trigger>
      <Popover.Portal>
        <Popover.Positioner side={side} align={align} sideOffset={6} collisionPadding={12} className="z-50">
          <Popover.Popup ref={popup} className={cn(controlStyles.popover, "kalos-color-popup")}
            aria-label={label} initialFocus={() => canFocusPopup.current ? popup.current ?? false : false}>
            <ColorPanel state={state} presets={presets} />
          </Popover.Popup>
        </Popover.Positioner>
      </Popover.Portal>
    </Popover.Root>
    {name ? <input ref={hiddenInput} type="hidden" name={name} form={form} disabled={disabled} value={state.hex} /> : null}
  </>;
}

export type Hsva = { h: number; s: number; v: number; a: number };
type Rgba = { r: number; g: number; b: number; a: number };

export const defaultColor = "#0190fe";
export const clampColor = (value: number, max = 1) => Math.min(max, Math.max(0, value));

const hexPattern = /^#?([\da-f]{3,4}|[\da-f]{6}|[\da-f]{8})$/i;
const component = "[+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)%?";
const commaRgb = new RegExp(`^(${component})\\s*,\\s*(${component})\\s*,\\s*(${component})(?:\\s*,\\s*(${component}))?$`);
const spaceRgb = new RegExp(`^(${component})\\s+(${component})\\s+(${component})(?:\\s*/\\s*(${component}))?$`);
export const completeColorInput = /^(?:#?(?:[\da-f]{6}|[\da-f]{8})|rgba?\(.*\))$/i;

function parseColor(input: string): Rgba | undefined {
  const text = input.trim();
  const hex = hexPattern.exec(text)?.[1];
  if (hex) {
    const digits = hex.length <= 4 ? [...hex].map((digit) => digit.repeat(2)).join("") : hex;
    const byte = (offset: number) => Number.parseInt(digits.slice(offset, offset + 2), 16);
    return { r: byte(0), g: byte(2), b: byte(4), a: digits.length === 8 ? byte(6) / 255 : 1 };
  }
  const args = /^rgba?\(([^)]*)\)$/i.exec(text)?.[1]?.trim();
  if (!args) return;
  const match = commaRgb.exec(args) ?? spaceRgb.exec(args);
  if (!match) return;
  const channel = (value: string) => clampColor(Number.parseFloat(value) / (value.endsWith("%") ? 100 : 255)) * 255;
  const opacity = match[4];
  return {
    r: channel(match[1]),
    g: channel(match[2]),
    b: channel(match[3]),
    a: opacity ? clampColor(Number.parseFloat(opacity) / (opacity.endsWith("%") ? 100 : 1)) : 1,
  };
}

function toHex({ r, g, b, a }: Rgba, alpha: boolean) {
  const byte = (value: number) => Math.round(value).toString(16).padStart(2, "0");
  const opacity = Math.round(a * 255);
  return `#${byte(r)}${byte(g)}${byte(b)}${alpha && opacity < 255 ? byte(opacity) : ""}`;
}

export function normalizeColor(input: string, alpha: boolean) {
  const color = parseColor(input);
  return color ? toHex(color, alpha) : undefined;
}

export function colorToHsva(hex: string, previous?: Hsva): Hsva {
  const rgba = parseColor(hex) ?? { r: 1, g: 144, b: 254, a: 1 };
  const r = rgba.r / 255;
  const g = rgba.g / 255;
  const b = rgba.b / 255;
  const v = Math.max(r, g, b);
  const chroma = v - Math.min(r, g, b);
  let h = previous?.h ?? 0;
  if (chroma) {
    if (v === r) h = (g - b) / chroma;
    else if (v === g) h = (b - r) / chroma + 2;
    else h = (r - g) / chroma + 4;
    h = (h * 60 + 360) % 360;
  }
  // Gray has no hue. Black also has no saturation to recover.
  return { h, s: v ? chroma / v : previous?.s ?? 0, v, a: rgba.a };
}

export function hsvaToHex({ h, s, v, a }: Hsva, alpha: boolean) {
  const channel = (offset: number) => {
    const sector = (offset + h / 60) % 6;
    return 255 * v * (1 - s * Math.max(0, Math.min(sector, 4 - sector, 1)));
  };
  return toHex({ r: channel(5), g: channel(3), b: channel(1), a }, alpha);
}

