"use client";

import { RadioGroup } from "@base-ui/react/radio-group";
import { Radio } from "@base-ui/react/radio";
import { Tabs } from "@base-ui/react/tabs";
import {
  SegmentedControlView,
  type KalosSegmentedControlProps,
} from "@/components/ui/kalos-segmented-control-view";

export type {
  KalosSegmentOption,
  KalosSegmentedControlProps,
} from "@/components/ui/kalos-segmented-control-view";

export function KalosSegmentedControl<T extends string = string>(
  props: KalosSegmentedControlProps<T>,
) {
  return (
    <SegmentedControlView
      {...props}
      onChange={(next) => props.onChange?.(next as T)}
      renderControl={({
        options,
        value,
        onChange,
        disabled,
        groupProps,
        optionProps,
        content,
      }) =>
        props.kind === "tabs" ? (
          <Tabs.Root
            value={value}
            onValueChange={(next) => {
              if (typeof next === "string") onChange(next);
            }}
          >
            <Tabs.List {...groupProps} activateOnFocus>
              {options.map((option) => (
                <Tabs.Tab
                  key={option.value}
                  value={option.value}
                  disabled={disabled || option.disabled}
                  {...optionProps(option)}
                >
                  {content(option)}
                </Tabs.Tab>
              ))}
            </Tabs.List>
          </Tabs.Root>
        ) : (
          <RadioGroup
            {...groupProps}
            value={value}
            onValueChange={onChange}
            disabled={disabled}
          >
            {options.map((option) => (
              <Radio.Root
                key={option.value}
                value={option.value}
                disabled={option.disabled}
                {...optionProps(option)}
              >
                {content(option)}
              </Radio.Root>
            ))}
          </RadioGroup>
        )
      }
    />
  );
}

"use client";

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type HTMLAttributes,
  type ReactNode,
  type RefObject,
} from "react";
import {
  controlStyles,
  segmentedControlCss,
} from "@/components/ui/kalos-styles";
import { cn } from "@/lib/utils";

export type KalosSegmentOption<T extends string = string> = {
  value: T;
  label?: ReactNode;
  icon?: ReactNode;
  count?: number | string;
  badge?: ReactNode;
  disabled?: boolean;
  ariaLabel?: string;
  /** kind="tabs" 时关联的外部面板 ID。 */
  controls?: string;
};

export type KalosSegmentedControlProps<T extends string = string> = {
  options: KalosSegmentOption<T>[];
  value?: T;
  defaultValue?: T;
  onChange?: (value: T) => void;
  size?: "sm" | "md" | "lg";
  variant?: "buttons" | "tray" | "underline";
  fullWidth?: boolean;
  kind?: "radio" | "tabs";
  disabled?: boolean;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  className?: string;
};

export type SegmentControlBindings = {
  options: KalosSegmentOption[];
  value: string;
  onChange: (value: string) => void;
  disabled: boolean;
  groupProps: Pick<
    HTMLAttributes<HTMLDivElement>,
    | "className"
    | "aria-label"
    | "aria-labelledby"
    | "onPointerDownCapture"
    | "onPointerMoveCapture"
    | "onPointerUpCapture"
    | "onPointerCancelCapture"
    | "onLostPointerCaptureCapture"
    | "onKeyDownCapture"
  > & { ref: RefObject<HTMLDivElement | null> };
  optionProps: (option: KalosSegmentOption) => {
    className: string;
    "data-segment": string;
    "data-active": boolean | undefined;
    "aria-label": string | undefined;
    "aria-controls": string | undefined;
  };
  content: (option: KalosSegmentOption) => ReactNode;
};

/** Visuals and pointer motion for Base UI radio and tab primitives. */
export function SegmentedControlView({
  renderControl,
  ...props
}: KalosSegmentedControlProps & {
  renderControl: (bindings: SegmentControlBindings) => ReactNode;
}) {
  const {
    options: rawOptions,
    value: controlled,
    defaultValue,
    onChange,
    disabled = false,
    kind = "radio",
    size = "md",
    variant = "buttons",
    fullWidth = false,
    className,
  } = props;
  const options = rawOptions.filter(
    (option, index, all) =>
      all.findIndex((other) => other.value === option.value) === index,
  );
  const [inner, setInner] = useState(
    () => defaultValue ?? options.find((option) => !option.disabled)?.value,
  );
  const value =
    controlled ??
    (options.some((option) => option.value === inner && !option.disabled)
      ? inner
      : options.find((option) => !option.disabled)?.value) ??
    "";
  const root = useRef<HTMLDivElement>(null);
  const scroller = useRef<HTMLDivElement>(null);
  const track = useRef<HTMLDivElement>(null);
  const pill = useRef<HTMLSpanElement>(null);
  const press = useRef<{
    id: number;
    x: number;
    y: number;
    touch: boolean;
    moved: boolean;
    drag: boolean;
  } | null>(null);
  const suppressClick = useRef(false);
  const select = (next: string) => {
    if (
      disabled ||
      next === value ||
      !options.some((option) => option.value === next && !option.disabled)
    )
      return;
    if (controlled === undefined) setInner(next);
    onChange?.(next);
  };

  useLayoutEffect(() => {
    const group = track.current,
      scroll = scroller.current,
      indicator = pill.current;
    if (!group || !scroll || !indicator) return;
    let frame = 0;
    const measure = () => {
      const items = Array.from(
        group.querySelectorAll<HTMLElement>("[data-segment]"),
      );
      const active = items.find((item) => item.dataset.segment === value);
      // Native tab implementations generate panel IDs. Honor the public controls API for external panels.
      if (kind === "tabs")
        items.forEach((item) => {
          const controls = options.find(
            (option) => option.value === item.dataset.segment,
          )?.controls;
          if (controls) item.setAttribute("aria-controls", controls);
          else item.removeAttribute("aria-controls");
        });
      if (!active) {
        indicator.style.opacity = "0";
        return;
      }
      const groupRect = group.getBoundingClientRect();
      const target =
        variant === "underline"
          ? (active.querySelector<HTMLElement>(".kalos-segment__content") ??
            active)
          : active;
      const rect = target.getBoundingClientRect();
      // The preview may scale an ancestor; the indicator needs unscaled CSS coordinates.
      const width = parseFloat(getComputedStyle(group).width) || group.offsetWidth;
      const scaleX = groupRect.width / width || 1;
      const x = (rect.left - groupRect.left) / scaleX;
      const previous = parseFloat(indicator.style.left) || 0;
      indicator.dataset.direction = x > previous ? "right" : "left";
      indicator.style.left = `${x}px`;
      indicator.style.right = `${width - x - rect.width / scaleX}px`;
      indicator.style.opacity = "1";
      if (!indicator.dataset.ready) {
        indicator.style.transition = "none";
        void indicator.offsetWidth;
        indicator.style.transition = "";
        indicator.dataset.ready = "true";
      }
      const overflow = scroll.scrollWidth - scroll.clientWidth;
      root.current?.toggleAttribute("data-overflow", overflow > 1);
      scroll.style.setProperty(
        "--segment-fade-left",
        scroll.scrollLeft > 1 ? "20px" : "0px",
      );
      scroll.style.setProperty(
        "--segment-fade-right",
        scroll.scrollLeft < overflow - 1 ? "20px" : "0px",
      );
    };
    const schedule = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(measure);
    };
    measure();
    const observer = new ResizeObserver(schedule);
    observer.observe(group);
    observer.observe(scroll);
    group
      .querySelectorAll("[data-segment], .kalos-segment__content")
      .forEach((item) => observer.observe(item));
    scroll.addEventListener("scroll", schedule, { passive: true });
    const active = group.querySelector<HTMLElement>("[data-active=true]");
    if (active && scroll.scrollWidth > scroll.clientWidth + 1) {
      const a = active.getBoundingClientRect(),
        s = scroll.getBoundingClientRect();
      const scaleX = s.width / scroll.offsetWidth || 1;
      if (a.left < s.left || a.right > s.right)
        scroll.scrollTo({
          left:
            scroll.scrollLeft +
            (a.left - s.left) / scaleX -
            (scroll.clientWidth - a.width / scaleX) / 2,
          behavior: "smooth",
        });
    }
    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
      scroll.removeEventListener("scroll", schedule);
    };
  }, [kind, options, value, size, variant, fullWidth]);

  useEffect(() => {
    const node = track.current;
    if (!node) return;
    // Capture only real drags; native click behavior remains with Base UI.
    const cancelClick = (event: MouseEvent) => {
      if (suppressClick.current) {
        event.preventDefault();
        event.stopImmediatePropagation();
        suppressClick.current = false;
      }
    };
    node.addEventListener("click", cancelClick, true);
    return () => node.removeEventListener("click", cancelClick, true);
  }, [kind]);

  const atPointer = (clientX: number) => {
    const items = Array.from(
      track.current?.querySelectorAll<HTMLElement>("[data-segment]") ?? [],
    );
    return items.reduce<HTMLElement | undefined>((best, item) => {
      const distance = (el: HTMLElement) => {
        const rect = el.getBoundingClientRect();
        return Math.max(rect.left - clientX, clientX - rect.right, 0);
      };
      return !best || distance(item) < distance(best) ? item : best;
    }, undefined);
  };
  const finishPress = () => {
    press.current = null;
    root.current?.removeAttribute("data-pressed");
  };
  const groupProps: SegmentControlBindings["groupProps"] = {
    ref: track,
    className: "kalos-segment__track",
    "aria-label": props["aria-label"],
    "aria-labelledby": props["aria-labelledby"],
    onPointerDownCapture(event) {
      suppressClick.current = false;
      const item = (event.target as Element).closest<HTMLElement>(
        "[data-segment]",
      );
      if (
        event.button !== 0 ||
        disabled ||
        !item ||
        options.find((option) => option.value === item.dataset.segment)
          ?.disabled
      )
        return;
      const touch = event.pointerType === "touch";
      press.current = {
        id: event.pointerId,
        x: event.clientX,
        y: event.clientY,
        touch,
        moved: false,
        drag:
          !touch ||
          (item.dataset.segment === value &&
            !root.current?.hasAttribute("data-overflow")),
      };
      root.current?.setAttribute("data-pressed", "");
    },
    onPointerMoveCapture(event) {
      const held = press.current;
      if (!held || held.id !== event.pointerId) return;
      if (
        Math.hypot(event.clientX - held.x, event.clientY - held.y) <
        (held.touch ? 8 : 3)
      )
        return;
      held.moved = true;
      suppressClick.current = true;
      if (!held.drag) return;
      event.currentTarget.setPointerCapture(event.pointerId);
      const item = atPointer(event.clientX);
      if (item?.dataset.segment) select(item.dataset.segment);
    },
    onPointerUpCapture(event) {
      if (press.current?.moved && press.current.drag) {
        event.preventDefault();
        event.stopPropagation();
        const item = atPointer(event.clientX);
        if (item?.dataset.segment) {
          select(item.dataset.segment);
          (
            item.querySelector<HTMLInputElement>('input[type="radio"]') ?? item
          ).focus({ preventScroll: true });
        }
      }
      finishPress();
    },
    onPointerCancelCapture: finishPress,
    onLostPointerCaptureCapture: finishPress,
    onKeyDownCapture(event) {
      const enabled = options.filter((option) => !option.disabled);
      if (disabled || !enabled.length) return;
      if (kind === "radio" && event.key === "Enter") {
        const item = (event.target as Element).closest<HTMLElement>(
          "[data-segment]",
        );
        if (item?.dataset.segment) {
          event.preventDefault();
          event.stopPropagation();
          select(item.dataset.segment);
        }
        return;
      }
      const previous =
        event.key === "ArrowLeft" ||
        (kind === "radio" && event.key === "ArrowUp");
      const next =
        event.key === "ArrowRight" ||
        (kind === "radio" && event.key === "ArrowDown");
      if (!previous && !next && event.key !== "Home" && event.key !== "End")
        return;
      event.preventDefault();
      event.stopPropagation();
      const index = enabled.findIndex((option) => option.value === value);
      const option =
        enabled[
          event.key === "Home"
            ? 0
            : event.key === "End"
              ? enabled.length - 1
              : (index + (previous ? -1 : 1) + enabled.length) % enabled.length
        ];
      select(option.value);
      const item = Array.from(
        track.current?.querySelectorAll<HTMLElement>("[data-segment]") ?? [],
      ).find((item) => item.dataset.segment === option.value);
      (
        item?.querySelector<HTMLInputElement>('input[type="radio"]') ?? item
      )?.focus({ preventScroll: true });
    },
  };
  const content = (option: KalosSegmentOption) => (
    <span className="kalos-segment__content">
      {option.icon && (
        <span aria-hidden="true" className="kalos-segment__icon">
          {option.icon}
        </span>
      )}
      {(option.label != null || !option.icon) && (
        <span>{option.label ?? option.value}</span>
      )}
      {option.count != null &&
        (typeof option.count !== "number" || Number.isFinite(option.count)) && (
          <span key={option.count} className="kalos-segment__count">
            {typeof option.count === "number"
              ? option.count.toLocaleString("zh-CN")
              : option.count}
          </span>
        )}
      {option.badge != null && (
        <span className="kalos-segment__badge">{option.badge}</span>
      )}
    </span>
  );
  return (
    <div
      ref={root}
      className={cn(controlStyles.segmentedControl, "kalos-segment", className)}
      data-size={size}
      data-variant={variant}
      data-full={fullWidth || undefined}
      data-disabled={disabled || undefined}
    >
      <style href="kalos-segmented-control" precedence="default">
        {segmentedControlCss}
      </style>
      <div ref={scroller} className="kalos-segment__scroller">
        <div className="kalos-segment__positioner">
          <span
            ref={pill}
            className="kalos-segment__indicator"
            aria-hidden="true"
          />
          {renderControl({
            options,
            value,
            onChange: select,
            disabled,
            groupProps,
            optionProps: (option) => ({
              className: "kalos-segment__option",
              "data-segment": option.value,
              "data-active": option.value === value || undefined,
              "aria-label": option.ariaLabel,
              "aria-controls": kind === "tabs" ? option.controls : undefined,
            }),
            content,
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useLayoutEffect, useRef, type ComponentProps, type CSSProperties } from "react";
import { Button } from "@base-ui/react/button";
import { ChevronLeft, ChevronRight, MoreHorizontal } from "lucide-react";
import { KalosSelect } from "./kalos-select";
import { paginationCss } from "@/components/ui/kalos-pagination-styles";
import { paginationPageForSize, paginationSizes, paginationState } from "@/components/ui/kalos-pagination-model";
import { cn } from "@/lib/utils";

export interface KalosPaginationProps extends ComponentProps<"nav"> {
  page: number;
  onPageChange: (page: number) => void;
  total?: number;
  pageSize?: number;
  pageCount?: number;
  pageSizes?: number[];
  onPageSizeChange?: (pageSize: number) => void;
  siblings?: number;
  compact?: boolean;
  disabled?: boolean;
}

export function KalosPagination({
  page, onPageChange, total, pageSize = 20, pageCount, pageSizes, onPageSizeChange,
  siblings = 1, compact = false, disabled = false, className, style,
  "aria-label": ariaLabel = "分页导航", children, ...props
}: KalosPaginationProps) {
  const state = paginationState({ page, total, pageSize, pageCount, siblings });
  const buttons = useRef(new Map<number, HTMLElement>());
  const focusPage = useRef<number | null>(null);
  useLayoutEffect(() => {
    if (focusPage.current === null) return;
    // A keyed page button may move when an ellipsis changes sides.
    const target = buttons.current.get(state.page);
    if (target && (document.activeElement === document.body || target.parentElement?.parentElement?.contains(document.activeElement))) {
      target.focus({ preventScroll: true });
    }
    focusPage.current = null;
  }, [state.page]);

  const change = (next: number, followFocus = false) => {
    if (disabled || next === state.page || next < 1 || next > state.pageCount) return;
    if (followFocus) focusPage.current = next;
    onPageChange(next);
  };
  const format = (value: number) => value.toLocaleString("zh-CN");
  const summary = state.total === undefined
    ? `第 ${format(state.page)} / ${format(state.pageCount)} 页`
    : `共 ${format(state.total)} 条`;

  return <nav {...props} aria-label={ariaLabel} data-disabled={disabled || undefined}
    className={cn("kalos-pagination", className)} data-compact={compact || undefined}
    style={{ "--pg-digits": String(state.pageCount).length, ...style } as CSSProperties}>
    <style>{paginationCss}</style>
    <span className="kalos-pagination-summary" role="status" aria-live="polite" aria-atomic="true">{summary}{state.total !== undefined ? <span className="sr-only">，第 {format(state.page)} / {format(state.pageCount)} 页</span> : null}</span>
    <ul className="kalos-pagination-pages">
      <li><Button type="button" className="kalos-pagination-button" aria-label="上一页"
        disabled={disabled || state.page <= 1} focusableWhenDisabled={!disabled}
        onClick={() => change(state.page - 1)}><ChevronLeft aria-hidden="true" /></Button></li>
      {!compact ? state.items.map(item => <li key={item} className="kalos-pagination-number">
        {typeof item === "number" ? <Button type="button" className="kalos-pagination-button"
          ref={node => { if (node) buttons.current.set(item, node); else buttons.current.delete(item); }}
          aria-label={`第 ${format(item)} 页`} aria-current={item === state.page ? "page" : undefined}
          disabled={disabled} onClick={() => change(item, true)}>{item}</Button>
          : <span className="kalos-pagination-ellipsis" aria-hidden="true"><MoreHorizontal /></span>}
      </li>) : null}
      <li><Button type="button" className="kalos-pagination-button" aria-label="下一页"
        disabled={disabled || state.page >= state.pageCount} focusableWhenDisabled={!disabled}
        onClick={() => change(state.page + 1)}><ChevronRight aria-hidden="true" /></Button></li>
    </ul>
    {pageSizes?.length ? <div className="kalos-pagination-size">
      <KalosSelect label="每页条数" clearable={false} disabled={disabled || !onPageSizeChange}
        value={String(state.pageSize)} items={paginationSizes(pageSizes, state.pageSize).map(size => ({ value: String(size), label: `${format(size)}条` }))}
        onValueChange={value => {
          if (disabled || !onPageSizeChange) return;
          const size = Number(value);
          if (size === state.pageSize) return;
          onPageSizeChange(size);
          onPageChange(paginationPageForSize(state, size));
        }} />
    </div> : null}
    {children}
  </nav>;
}

export type KalosPaginationItem = number | "start-ellipsis" | "end-ellipsis";

function integer(value: number, fallback: number, min = 0) {
  return Number.isFinite(value) ? Math.max(min, Math.min(Number.MAX_SAFE_INTEGER, Math.floor(value))) : fallback;
}

export function paginationItems(page: number, pageCount: number, siblings = 1): KalosPaginationItem[] {
  const nearby = Math.min(5, integer(siblings, 1));
  const slots = nearby * 2 + 5;
  if (pageCount <= slots) return Array.from({ length: pageCount }, (_, index) => index + 1);
  const middleCount = nearby * 2 + 1;
  if (page <= nearby + 3) return [
    ...Array.from({ length: middleCount + 2 }, (_, index) => index + 1), "end-ellipsis", pageCount,
  ];
  if (page >= pageCount - nearby - 2) return [
    1, "start-ellipsis", ...Array.from({ length: middleCount + 2 }, (_, index) => pageCount - middleCount - 1 + index),
  ];
  return [1, "start-ellipsis", ...Array.from({ length: middleCount }, (_, index) => page - nearby + index), "end-ellipsis", pageCount];
}

export function paginationState({ page, pageSize = 20, total, pageCount, siblings = 1 }: {
  page: number;
  pageSize?: number;
  total?: number;
  pageCount?: number;
  siblings?: number;
}) {
  const size = integer(pageSize, 20, 1);
  const rows = total === undefined ? undefined : integer(total, 0);
  const count = rows === undefined ? integer(pageCount ?? 1, 1, 1) : Math.max(1, Math.ceil(rows / size));
  const current = Math.min(count, integer(page, 1, 1));
  return {
    page: current, pageSize: size, pageCount: count, total: rows,
    from: rows === 0 ? 0 : (current - 1) * size + 1,
    to: rows === undefined ? current * size : Math.min(current * size, rows),
    items: paginationItems(current, count, siblings),
  };
}

export function paginationPageForSize(state: ReturnType<typeof paginationState>, nextSize: number) {
  const size = integer(nextSize, state.pageSize, 1);
  const count = state.total === undefined ? state.pageCount : Math.max(1, Math.ceil(state.total / size));
  return Math.min(count, Math.floor((state.page - 1) * state.pageSize / size) + 1);
}

export function paginationSizes(sizes: number[], current: number) {
  return [...new Set([...sizes.filter(size => Number.isSafeInteger(size) && size > 0), current])].sort((a, b) => a - b);
}

"use client";
import { controlStyles } from "@/components/ui/kalos-styles";
import type { ReactNode } from "react";
import {
  Accordion,
  AccordionItem,
